#include <bits/stdc++.h>
using namespace std;

using ll = long long;
const ll INF = (1LL << 62);

struct Edge {
    int to;
    ll w;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M, Q;
    cin >> N >> M >> Q;

    int S, T;
    cin >> S >> T;
    --S; --T;

    vector<int> U(M), V(M);
    vector<ll> W(M);

    vector<vector<Edge>> g(N), rg(N);
    map<pair<int,int>, ll> weightMap;

    for (int i = 0; i < M; ++i) {
        cin >> U[i] >> V[i] >> W[i];
        --U[i]; --V[i];
        g[U[i]].push_back({V[i], W[i]});
        rg[V[i]].push_back({U[i], W[i]});

        auto key = make_pair(U[i], V[i]);
        if (!weightMap.count(key) || weightMap[key] > W[i]) weightMap[key] = W[i];
    }

    auto dijkstra = [&](int src, const vector<vector<Edge>>& adj) {
        vector<ll> dist(N, INF);
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        dist[src] = 0;
        pq.push({0, src});

        while (!pq.empty()) {
            auto [d, v] = pq.top();
            pq.pop();
            if (d != dist[v]) continue;
            for (auto &e : adj[v]) {
                if (dist[e.to] > d + e.w) {
                    dist[e.to] = d + e.w;
                    pq.push({dist[e.to], e.to});
                }
            }
        }
        return dist;
    };

    vector<ll> distS = dijkstra(S, g);
    vector<ll> distT = dijkstra(T, rg);

    ll shortest = distS[T];

    // Build DAG of shortest-path edges
    vector<vector<int>> dag(N), rdag(N);
    vector<int> indeg(N, 0);
    for (int u = 0; u < N; ++u) {
        if (distS[u] == INF) continue;
        for (auto &e : g[u]) {
            int v = e.to;
            if (distT[v] == INF) continue;
            if (distS[u] + e.w + distT[v] == shortest) {
                dag[u].push_back(v);
                rdag[v].push_back(u);
                indeg[v]++;
            }
        }
    }

    // Topological order on shortest path DAG
    queue<int> qu;
    for (int i = 0; i < N; ++i) {
        if (distS[i] != INF && distT[i] != INF && indeg[i] == 0) qu.push(i);
    }

    vector<int> topo;
    while (!qu.empty()) {
        int v = qu.front(); qu.pop();
        topo.push_back(v);
        for (int to : dag[v]) {
            if (--indeg[to] == 0) qu.push(to);
        }
    }

    // Count number of shortest paths from S and to T modulo two primes
    const int MOD1 = 1000000007;
    const int MOD2 = 1000000009;

    vector<int> ways1S(N, 0), ways2S(N, 0), ways1T(N, 0), ways2T(N, 0);
    ways1S[S] = 1;
    ways2S[S] = 1;

    for (int v : topo) {
        for (int to : dag[v]) {
            ways1S[to] += ways1S[v];
            if (ways1S[to] >= MOD1) ways1S[to] -= MOD1;
            ways2S[to] += ways2S[v];
            if (ways2S[to] >= MOD2) ways2S[to] -= MOD2;
        }
    }

    ways1T[T] = 1;
    ways2T[T] = 1;
    for (int i = (int)topo.size() - 1; i >= 0; --i) {
        int v = topo[i];
        for (int p : rdag[v]) {
            ways1T[p] += ways1T[v];
            if (ways1T[p] >= MOD1) ways1T[p] -= MOD1;
            ways2T[p] += ways2T[v];
            if (ways2T[p] >= MOD2) ways2T[p] -= MOD2;
        }
    }

    int total1 = ways1S[T];
    int total2 = ways2S[T];

    auto onAllShortestPaths = [&](int u, int v, ll w) -> bool {
        if (distS[u] == INF || distT[v] == INF) return false;
        if (distS[u] + w + distT[v] != shortest) return false;

        long long c1 = 1LL * ways1S[u] * ways1T[v] % MOD1;
        long long c2 = 1LL * ways2S[u] * ways2T[v] % MOD2;
        return c1 == total1 && c2 == total2;
    };

    while (Q--) {
        int id;
        cin >> id;
        --id;

        int a = U[id], b = V[id];
        ll w = W[id];

        ll ans = shortest;

        // If reversed edge already exists as b -> a with weight <= w,
        // reversing cannot create anything better than using that direction already.
        auto it = weightMap.find({b, a});
        ll revBest = (it == weightMap.end() ? INF : it->second);

        if (revBest > w) {
            if (distS[b] != INF && distT[a] != INF) {
                ans = min(ans, distS[b] + w + distT[a]);
            }
        }

        // If the removed edge is on every shortest path, shortest path may increase.
        if (onAllShortestPaths(a, b, w)) {
            // Need shortest path avoiding this edge.
            // Since only this edge is removed and reversed, if new candidate above
            // is not enough, we need recompute once for this query.
            vector<ll> dist(N, INF);
            priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
            dist[S] = 0;
            pq.push({0, S});

            while (!pq.empty()) {
                auto [d, v] = pq.top();
                pq.pop();
                if (d != dist[v]) continue;
                for (auto &e : g[v]) {
                    int to = e.to;
                    ll ww = e.w;
                    if (v == a && to == b && ww == w) continue; // remove this one edge occurrence
                    if (dist[to] > d + ww) {
                        dist[to] = d + ww;
                        pq.push({dist[to], to});
                    }
                }
                // add reversed version of removed edge
                if (v == b) {
                    if (dist[a] > d + w) {
                        dist[a] = d + w;
                        pq.push({dist[a], a});
                    }
                }
            }
            ans = dist[T];
        }

        if (ans >= INF / 2) cout << -1 << '\n';
        else cout << ans << '\n';
    }

    return 0;
}

