#define INF 1000000000
#define MAXN 1005
#define MAXM 10005

int N, M, S, T, Q;
int eu[MAXM], ev[MAXM], ew[MAXM];
// adjacency list
int head[MAXN], nxt[MAXM*2], to[MAXM*2], wt[MAXM*2], cnt;
int dist[MAXN];
int vis[MAXN];

void build() {
    memset(head, -1, sizeof(head));
    cnt = 0;
    for(int i = 0; i < M; i++) {
        to[cnt] = ev[i]; wt[cnt] = ew[i]; nxt[cnt] = head[eu[i]]; head[eu[i]] = cnt++;
    }
}

void dijkstra() {
    for(int i = 1; i <= N; i++) dist[i] = INF, vis[i] = 0;
    dist[S] = 0;
    for(int iter = 0; iter < N; iter++) {
        int u = -1;
        for(int i = 1; i <= N; i++) if(!vis[i] && (u == -1 || dist[i] < dist[u])) u = i;
        if(u == -1 || dist[u] == INF) break;
        vis[u] = 1;
        for(int e = head[u]; e != -1; e = nxt[e]) {
            int v = to[e], w = wt[e];
            if(dist[u] + w < dist[v]) dist[v] = dist[u] + w;
        }
    }
}

