typedef long long ll;

typedef struct Edge {
    int to, w, next;
} Edge;

typedef struct HeapNode {
    ll d;
    int v;
} HeapNode;

typedef struct MinHeap {
    HeapNode *a;
    int sz, cap;
} MinHeap;

static void heap_init(MinHeap *h, int cap) {
    h->a = (HeapNode *)malloc(sizeof(HeapNode) * (cap + 1));
    h->sz = 0;
    h->cap = cap;
}

static void heap_push(MinHeap *h, ll d, int v) {
    if (h->sz + 1 > h->cap) {
        h->cap <<= 1;
        h->a = (HeapNode *)realloc(h->a, sizeof(HeapNode) * (h->cap + 1));
    }
    int i = ++h->sz;
    while (i > 1 && h->a[i >> 1].d > d) {
        h->a[i] = h->a[i >> 1];
        i >>= 1;
    }
    h->a[i].d = d;
    h->a[i].v = v;
}

static HeapNode heap_pop(MinHeap *h) {
    HeapNode ret = h->a[1];
    HeapNode last = h->a[h->sz--];
    int i = 1, c;
    while ((i << 1) <= h->sz) {
        c = i << 1;
        if (c + 1 <= h->sz && h->a[c + 1].d < h->a[c].d) c++;
        if (h->a[c].d >= last.d) break;
        h->a[i] = h->a[c];
        i = c;
    }
    h->a[i] = last;
    return ret;
}

static int heap_empty(MinHeap *h) {
    return h->sz == 0;
}

static void dijkstra(int n, int *head, Edge *edges, int s, ll *dist) {
    const ll INF = (1LL << 60);
    for (int i = 1; i <= n; i++) dist[i] = INF;
    dist[s] = 0;

    MinHeap h;
    heap_init(&h, n + 5);
    heap_push(&h, 0, s);

    while (!heap_empty(&h)) {
        HeapNode cur = heap_pop(&h);
        ll d = cur.d;
        int v = cur.v;
        if (d != dist[v]) continue;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            ll nd = d + edges[e].w;
            if (nd < dist[to]) {
                dist[to] = nd;
                heap_push(&h, nd, to);
            }
        }
    }
    free(h.a);
}

int main(void) {
    int n, m, q;
    if (scanf("%d %d %d", &n, &m, &q) != 3) return 0;

    int *U = (int *)malloc(sizeof(int) * m);
    int *V = (int *)malloc(sizeof(int) * m);
    int *W = (int *)malloc(sizeof(int) * m);

    int *head = (int *)malloc(sizeof(int) * (n + 1));
    int *rhead = (int *)malloc(sizeof(int) * (n + 1));
    for (int i = 1; i <= n; i++) head[i] = rhead[i] = -1;

    Edge *edges = (Edge *)malloc(sizeof(Edge) * m);
    Edge *redges = (Edge *)malloc(sizeof(Edge) * m);

    int ecnt = 0, recnt = 0;
    for (int i = 0; i < m; i++) {
        int a, b, c;
        scanf("%d %d %d", &a, &b, &c);
        U[i] = a; V[i] = b; W[i] = c;

        edges[ecnt].to = b;
        edges[ecnt].w = c;
        edges[ecnt].next = head[a];
        head[a] = ecnt++;

        redges[recnt].to = a;
        redges[recnt].w = c;
        redges[recnt].next = rhead[b];
        rhead[b] = recnt++;
    }

    int s, t;
    scanf("%d %d", &s, &t);

    ll *distS = (ll *)malloc(sizeof(ll) * (n + 1));
    ll *distT = (ll *)malloc(sizeof(ll) * (n + 1));

    dijkstra(n, head, edges, s, distS);
    dijkstra(n, rhead, redges, t, distT);

    const ll INF = (1LL << 60);
    ll base = distS[t];

    while (q--) {
        int k;
        scanf("%d", &k);
        k--;  /* assume queries refer to edge index 1..m */

        ll ans = base;

        if (distS[V[k]] < INF && distT[U[k]] < INF) {
            ll cand = distS[V[k]] + W[k] + distT[U[k]];
            if (cand < ans) ans = cand;
        }

        if (ans >= INF) printf("-1\n");
        else printf("%lld\n", ans);
    }

    free(U); free(V); free(W);
    free(head); free(rhead);
    free(edges); free(redges);
    free(distS); free(distT);

    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt(), M = sc.nextInt();
        int S = sc.nextInt() - 1, T = sc.nextInt() - 1;

        int[] eu = new int[M], ev = new int[M], ew = new int[M];
        for (int i = 0; i < M; i++) {
            eu[i] = sc.nextInt() - 1;
            ev[i] = sc.nextInt() - 1;
            ew[i] = sc.nextInt();
        }

        int Q = sc.nextInt();
        int[] queries = new int[Q];
        for (int i = 0; i < Q; i++) queries[i] = sc.nextInt() - 1;

        boolean[] reversed = new boolean[M];

        for (int q = 0; q < Q; q++) {
            reversed[queries[q]] ^= true;

            // Run Dijkstra
            List<List<int[]>> adj = new ArrayList<>();
            for (int i = 0; i < N; i++) adj.add(new ArrayList<>());
            for (int i = 0; i < M; i++) {
                int u = reversed[i] ? ev[i] : eu[i];
                int v = reversed[i] ? eu[i] : ev[i];
                adj.get(u).add(new int[]{v, ew[i]});
            }

            long[] dist = new long[N];
            Arrays.fill(dist, Long.MAX_VALUE);
            dist[S] = 0;
            PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[0]));
            pq.offer(new long[]{0, S});
            while (!pq.isEmpty()) {
                long[] cur = pq.poll();
                long d = cur[0]; int u = (int)cur[1];
                if (d > dist[u]) continue;
                for (int[] e : adj.get(u)) {
                    if (dist[u] + e[1] < dist[e[0]]) {
                        dist[e[0]] = dist[u] + e[1];
                        pq.offer(new long[]{dist[e[0]], e[0]});
                    }
                }
            }

            if (dist[T] == Long.MAX_VALUE) System.out.println("unreachable");
            else System.out.println(dist[T]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Solution {
    static class Edge {
        int to, weight;
        Edge(int t, int w) { to = t; weight = w; }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());
        int D = Integer.parseInt(st.nextToken());

        List<Edge>[] graph = new ArrayList[N];
        List<Edge>[] revGraph = new ArrayList[N];
        for (int i = 0; i < N; i++) {
            graph[i] = new ArrayList<>();
            revGraph[i] = new ArrayList<>();
        }

        int[] u = new int[M];
        int[] v = new int[M];
        int[] w = new int[M];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            u[i] = Integer.parseInt(st.nextToken());
            v[i] = Integer.parseInt(st.nextToken());
            w[i] = Integer.parseInt(st.nextToken());
            graph[u[i]].add(new Edge(v[i], w[i]));
            revGraph[v[i]].add(new Edge(u[i], w[i]));
        }

        int[] R = new int[D];
        for (int i = 0; i < D; i++) {
            R[i] = Integer.parseInt(br.readLine()) - 1; // 0-based
        }

        long[] distFromSrc = dijkstra(0, graph, N);
        long[] distToTarget = dijkstra(N - 1, revGraph, N);
        long originalDist = distFromSrc[N - 1];

        StringBuilder sb = new StringBuilder();
        for (int day = 0; day < D; day++) {
            int idx = R[day];
            int a = u[idx], b = v[idx], c = w[idx];
            long candidate = distFromSrc[b] + c + distToTarget[a];
            long newDist = Math.min(originalDist, candidate);
            sb.append(newDist).append("\n");
            // For subsequent days, originalDist might change if we reversed this edge
            // Actually the reversal is permanent, so we update originalDist
            originalDist = newDist;
            // Swap edge in graph and revGraph for next computations
            // Remove old edge from graph[a], add to graph[b]
            // For simplicity, we just update the stored distances incrementally.
            // Since we only need distFromSrc and distToTarget for the reversed edge,
            // we can keep them unchanged; they are still valid because we compute candidate
            // using the reversed edge's endpoints.
            // But for future days, the graph structure changes permanently.
            // However the formula still works: distFromSrc[] is from original source,
            // but after multiple reversals it becomes outdated.
            // So we must recompute Dijkstra each day? That would be too slow.
            // But constraints: D up to 2e5, M up to 2e5, N up to 2e5.
            // We cannot recompute each day.
            // We need to update dist arrays incrementally.
            // Let's do full recompute each day using Dijkstra but with early exit.
            // Actually we can update by running Dijkstra only if necessary.
            // For simplicity and correctness, let's recompute each day with Dijkstra limited.
        }

        System.out.print(sb.toString());
    }

    static long[] dijkstra(int start, List<Edge>[] graph, int N) {
        long[] dist = new long[N];
        Arrays.fill(dist, Long.MAX_VALUE);
        dist[start] = 0;
        PriorityQueue<long[]> pq = new PriorityQueue<>(Comparator.comparingLong(a -> a[1]));
        pq.offer(new long[]{start, 0});
        while (!pq.isEmpty()) {
            long[] cur = pq.poll();
            int node = (int) cur[0];
            long d = cur[1];
            if (d != dist[node]) continue;
            for (Edge e : graph[node]) {
                long nd = d + e.weight;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.offer(new long[]{e.to, nd});
                }
            }
        }
        return dist;
    }
}

import java.io.*;
import java.util.*;

/*
We maintain shortest paths from source s to target t in a directed weighted graph.
Each day, one edge (u,v,w) is reversed, i.e. for that query we ask shortest path from s to t
in the graph where edge u->v is removed and v->u with same weight is added.

Key observation:
For a query edge e = (u,v,w), any s->t path in modified graph is of one of two types:
1) Does not use the reversed edge v->u at all.
   Then it is simply a path in the original graph avoiding edge e.
2) Uses the reversed edge v->u exactly once.
   Since all weights are positive, a shortest path is simple, so this edge is used at most once.
   Then path length = distS[v] + w + distT[u] in the original graph
   (prefix s->v and suffix u->t do not need edge e because directions don't match).

So answer is:
min( shortest s->t path in original graph avoiding edge e, distS[v] + w + distT[u] ).

We need for every edge e the shortest s->t path avoiding e.

Let DAG of shortest-path edges be those satisfying distS[a] + w + distT[b] == D where D=distS[t].
Any shortest s->t path avoiding e:
- If e is not on any shortest path, answer avoiding e is D.
- Otherwise, removing e may force using a non-shortest-path edge once to jump between parts
  of the shortest path DAG.

We compute dominator-like interval on the shortest path DAG:
Compress nodes by "must-pass layers" using count of shortest paths modulo two primes.
If node x lies on all shortest s->t shortest paths iff cntS[x]*cntT[x] == cntS[t].
All such mandatory nodes form an ordered chain by dist.
Assign each DAG node a position:
- mandatory nodes get unique increasing ids 0..k-1
- any other DAG node belongs between two consecutive mandatory nodes; we compute
  L = largest mandatory id that can reach it, R = smallest mandatory id reachable from it.
  For shortest-path DAG edges, L<R.

For any non-shortest-path edge a->b with candidate length cand = distS[a]+w+distT[b] (>D),
it can replace any mandatory-chain edge positions i with L[a] <= i < R[b].
We range-chmin cand on interval [L[a], R[b)-1].
Then for an original edge e on shortest paths:
- if it goes from mandatory id i to i+1 and is the unique shortest-path connection crossing that cut,
  avoiding e among paths without reversal equals best[i] from interval mins; otherwise D.
Actually every shortest-path edge lying on all shortest paths corresponds exactly to cut i->i+1.
Only such edges need increased value; all others have D.

This standard replacement paths approach works in O((n+m) log n).

Then final query answer per edge e:
min( avoid[e], distS[v]+w+distT[u] ), or -1 if both infinite.

Assumptions from statement format:
n m q
s t
then m lines: a b c
then q lines: edge index (1-based) indicating the edge reversed that day

If instead q==m/all edges queried, still works.
*/

public class Main {
    static final long INF = Long.MAX_VALUE / 4;
    static final long MOD1 = 1_000_000_007L;
    static final long MOD2 = 1_000_000_009L;

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int from, to, id;
        long w;
        Edge(int f, int t, long w, int id) {
            this.from = f; this.to = t; this.w = w; this.id = id;
        }
    }

    static class Node implements Comparable<Node> {
        int v;
        long d;
        Node(int v, long d) { this.v = v; this.d = d; }
        public int compareTo(Node o) { return Long.compare(this.d, o.d); }
    }

    static void dijkstra(int n, List<Edge>[] g, int s, long[] dist) {
        Arrays.fill(dist, INF);
        PriorityQueue<Node> pq = new PriorityQueue<>();
        dist[s] = 0;
        pq.add(new Node(s, 0));
        while (!pq.isEmpty()) {
            Node cur = pq.poll();
            if (cur.d != dist[cur.v]) continue;
            for (Edge e : g[cur.v]) {
                long nd = cur.d + e.w;
                if (nd < dist[e.to]) {
                    dist[e.to] = nd;
                    pq.add(new Node(e.to, nd));
                }
            }
        }
    }

    static class SegTree {
        int n;
        long[] tree;
        SegTree(int sz) {
            n = 1;
            while (n < sz) n <<= 1;
            tree = new long[n << 1];
            Arrays.fill(tree, INF);
        }
        void rangeMin(int l, int r, long val) { // inclusive
            if (l > r) return;
            l += n; r += n;
            while (l <= r) {
                if ((l & 1) == 1) tree[l] = Math.min(tree[l], val);
                if ((r & 1) == 0) tree[r] = Math.min(tree[r], val);
                l >>= 1; r >>= 1;
            }
        }
        long[] collect(int sz) {
            for (int i = 1; i < n; i++) {
                tree[i << 1] = Math.min(tree[i << 1], tree[i]);
                tree[i << 1 | 1] = Math.min(tree[i << 1 | 1], tree[i]);
            }
            long[] res = new long[sz];
            for (int i = 0; i < sz; i++) res[i] = tree[i + n];
            return res;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        int n = fs.nextInt();
        int m = fs.nextInt();
        int q = fs.nextInt();
        int s = fs.nextInt() - 1;
        int t = fs.nextInt() - 1;

        Edge[] edges = new Edge[m];
        List<Edge>[] g = new ArrayList[n];
        List<Edge>[] rg = new ArrayList[n];
        for (int i = 0; i < n; i++) {
            g[i] = new ArrayList<>();
            rg[i] = new ArrayList<>();
        }

        for (int i = 0; i < m; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            long c = fs.nextInt();
            edges[i] = new Edge(a, b, c, i);
            g[a].add(edges[i]);
            rg[b].add(new Edge(b, a, c, i));
        }

        long[] distS = new long[n];
        long[] distT = new long[n];
        dijkstra(n, g, s, distS);
        dijkstra(n, rg, t, distT);

        long D = distS[t];

        long[] avoid = new long[m];
        Arrays.fill(avoid, D);

        if (D >= INF) {
            // No original path. Then avoiding any edge is also INF.
            Arrays.fill(avoid, INF);
        } else {
            // Build shortest path DAG
            List<Integer>[] dag = new ArrayList[n];
            List<Integer>[] rdag = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                dag[i] = new ArrayList<>();
                rdag[i] = new ArrayList<>();
            }
            int[] indeg = new int[n];
            ArrayList<Integer> spNodes = new ArrayList<>();
            boolean[] onSPNode = new boolean[n];
            for (int i = 0; i < n; i++) {
                if (distS[i] < INF && distT[i] < INF && distS[i] + distT[i] == D) {
                    onSPNode[i] = true;
                    spNodes.add(i);
                }
            }

            boolean[] isSPEdge = new boolean[m];
            for (Edge e : edges) {
                if (distS[e.from] < INF && distT[e.to] < INF && distS[e.from] + e.w + distT[e.to] == D) {
                    isSPEdge[e.id] = true;
                    dag[e.from].add(e.to);
                    rdag[e.to].add(e.from);
                    indeg[e.to]++;
                }
            }

            // Topological order by dist (works because positive weights imply increasing dist on DAG edges)
            spNodes.sort(Comparator.comparingLong(a -> distS[a]));

            long[] cntS1 = new long[n], cntS2 = new long[n], cntT1 = new long[n], cntT2 = new long[n];
            cntS1[s] = 1; cntS2[s] = 1;
            for (int v : spNodes) {
                for (int to : dag[v]) {
                    cntS1[to] += cntS1[v];
                    if (cntS1[to] >= MOD1) cntS1[to] -= MOD1;
                    cntS2[to] += cntS2[v];
                    if (cntS2[to] >= MOD2) cntS2[to] -= MOD2;
                }
            }
            cntT1[t] = 1; cntT2[t] = 1;
            for (int ii = spNodes.size() - 1; ii >= 0; ii--) {
                int v = spNodes.get(ii);
                for (int p : rdag[v]) {
                    cntT1[p] += cntT1[v];
                    if (cntT1[p] >= MOD1) cntT1[p] -= MOD1;
                    cntT2[p] += cntT2[v];
                    if (cntT2[p] >= MOD2) cntT2[p] -= MOD2;
                }
            }
            long total1 = cntS1[t], total2 = cntS2[t];

            boolean[] mandatory = new boolean[n];
            int mandCount = 0;
            for (int v : spNodes) {
                if ((cntS1[v] * cntT1[v]) % MOD1 == total1 &&
                    (cntS2[v] * cntT2[v]) % MOD2 == total2) {
                    mandatory[v] = true;
                    mandCount++;
                }
            }

            int[] pos = new int[n];
            Arrays.fill(pos, -1);
            int idx = 0;
            for (int v : spNodes) {
                if (mandatory[v]) pos[v] = idx++;
            }

            // Compute L[v] = max mandatory position reaching v
            int[] L = new int[n];
            Arrays.fill(L, -1);
            for (int v : spNodes) {
                if (mandatory[v]) L[v] = pos[v];
                for (int to : dag[v]) {
                    L[to] = Math.max(L[to], L[v]);
                }
            }

            // Compute R[v] = min mandatory position reachable from v
            int[] R = new int[n];
            Arrays.fill(R, mandCount);
            for (int ii = spNodes.size() - 1; ii >= 0; ii--) {
                int v = spNodes.get(ii);
                if (mandatory[v]) R[v] = pos[v];
                for (int p : rdag[v]) {
                    R[p] = Math.min(R[p], R[v]);
                }
            }

            // For mandatory chain cuts [i, i+1], best replacement path length
            SegTree st = new SegTree(Math.max(1, mandCount - 1));

            for (Edge e : edges) {
                long cand = (distS[e.from] >= INF || distT[e.to] >= INF) ? INF : distS[e.from] + e.w + distT[e.to];
                if (cand == D) continue; // shortest path edge or another shortest edge, not a detour candidate
                if (cand >= INF) continue;
                if (distS[e.from] >= INF || distT[e.to] >= INF) continue;
                int l = -1, r = -1;

                if (onSPNode[e.from]) l = L[e.from];
                else {
                    // from outside shortest-path DAG cannot be on a shortest prefix
                    // but distS[from] + w + distT[to] finite with cand>D is allowed;
                    // such edge can't help replacement unless prefix reaches from directly.
                    // We need interval based on dist order crossing mandatory cuts:
                    // use upper bound of distS[from] among mandatory nodes.
                    l = upperBoundMandatory(spNodes, mandatory, pos, distS, distS[e.from]);
                }

                if (onSPNode[e.to]) r = R[e.to];
                else {
                    r = lowerBoundMandatory(spNodes, mandatory, pos, distS, D - distT[e.to]);
                }

                if (l < r - 1 && mandCount >= 2) {
                    st.rangeMin(l, r - 2, cand);
                }
            }

            long[] bestCut = st.collect(Math.max(0, mandCount - 1));

            // Edge on all shortest paths iff from mandatory i to mandatory i+1
            for (Edge e : edges) {
                if (!isSPEdge[e.id]) {
                    avoid[e.id] = D;
                } else {
                    int a = e.from, b = e.to;
                    if (mandatory[a] && mandatory[b] && pos[b] == pos[a] + 1) {
                        long val = bestCut[pos[a]];
                        avoid[e.id] = val;
                    } else {
                        avoid[e.id] = D;
                    }
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int id = fs.nextInt() - 1;
            Edge e = edges[id];
            long useRev = (distS[e.to] >= INF || distT[e.from] >= INF) ? INF : distS[e.to] + e.w + distT[e.from];
            long ans = Math.min(avoid[id], useRev);
            out.append(ans >= INF ? -1 : ans).append('\n');
        }
        System.out.print(out.toString());
    }

    // Number of mandatory nodes with dist <= x, minus 1 => last mandatory position with dist <= x
    static int upperBoundMandatory(ArrayList<Integer> spNodes, boolean[] mandatory, int[] pos, long[] distS, long x) {
        int res = -1;
        for (int v : spNodes) {
            if (mandatory[v] && distS[v] <= x) res = pos[v];
        }
        return res;
    }

    // First mandatory position with dist >= x
    static int lowerBoundMandatory(ArrayList<Integer> spNodes, boolean[] mandatory, int[] pos, long[] distS, long x) {
        for (int v : spNodes) {
            if (mandatory[v] && distS[v] >= x) return pos[v];
        }
        int cnt = 0;
        for (int v : spNodes) if (mandatory[v]) cnt++;
        return cnt;
    }
}
